// Active-tab origin the "Enable" button will request, captured up front so the
// permission request runs directly inside the user's click (no await before it,
// which would break the required user gesture). { origin, tabId } or null.
let detectTarget = null;

// Slug lookup cache: { artistName → slug }
const SLUG_CACHE_KEY = 'artistSlugCache';

// Look up the canonical slug for an artist name via the search API.
// This mirrors what the web app does (claimedSlug || result.id).
// Results are cached in chrome.storage.local so we don't re-fetch on every save.
async function lookupSlug(artistName) {
  if (!artistName) return null;

  // Check cache
  const { [SLUG_CACHE_KEY]: slugCache = {} } = await chrome.storage.local.get(SLUG_CACHE_KEY);
  const normalizedName = artistName.toLowerCase().trim();

  if (slugCache[normalizedName]) {
    return slugCache[normalizedName];
  }

  try {
    const response = await chrome.runtime.sendMessage({
      type: 'GET_RESULTS',
      artist: artistName,
    });

    if (!response || response.error) return null;

    const results = response.results || [];
    // Find the best-matching artist result
    const match = results.find(r =>
      r.type === 'artist' && r.name && r.name.toLowerCase() === normalizedName
    ) || results.find(r =>
      r.type === 'artist' && r.name && r.name.toLowerCase().includes(normalizedName)
    );

    if (match) {
      // claimedSlug/knownSlug are real `artists.slug` values. `match.id` is not — it is
      // 'known-<slug>'/'claimed-<slug>' for stored cards and a platform-derived id otherwise —
      // so it is only a last resort, kept so behaviour doesn't regress against an older deploy.
      const slug = match.claimedSlug || match.knownSlug || match.id;
      if (slug) {
        // Persist to cache
        slugCache[normalizedName] = slug;
        await chrome.storage.local.set({ [SLUG_CACHE_KEY]: slugCache });
        return slug;
      }
    }
  } catch {
    // Network error — fall back to slugifying locally
  }

  // Fallback: slugify the display name the same way the server does
  const fallbackSlug = artistName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  if (fallbackSlug) {
    slugCache[normalizedName] = fallbackSlug;
    await chrome.storage.local.set({ [SLUG_CACHE_KEY]: slugCache });
  }
  return fallbackSlug || null;
}

// ---- Auth ----

async function initAuth() {
  try {
    const { session } = await chrome.runtime.sendMessage({ type: 'AUTH_GET_SESSION' });
    if (session && session.user) {
      authSession = session;
      showLoggedInState(session.user);
    } else {
      authSession = false;
      showLoggedOutState();
    }
  } catch {
    // Service worker may be starting up — try reading from storage directly
    try {
      const session = await getStoredSession();
      if (session && session.user) {
        authSession = session;
        showLoggedInState(session.user);
      } else {
        authSession = false;
        showLoggedOutState();
      }
    } catch {
      authSession = false;
      showLoggedOutState();
    }
  }
}

function showLoggedInState(user) {
  elements.authSection.classList.add('hidden');
  elements.authLoggedIn.classList.remove('hidden');
  elements.authEmailDisplay.textContent = user.email || 'Signed in';
  elements.syncNowBtn.disabled = false;
  elements.syncNowBtn.textContent = '';
  // Rebuild the sync button content
  elements.syncNowBtn.innerHTML = '';
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('width', '14');
  svg.setAttribute('height', '14');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  const polyline = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
  polyline.setAttribute('points', '23 4 23 10 17 10');
  const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  path.setAttribute('d', 'M20.49 15a9 9 0 1 1-2.12-9.36L23 10');
  svg.appendChild(polyline);
  svg.appendChild(path);
  elements.syncNowBtn.appendChild(svg);
  elements.syncNowBtn.appendChild(document.createTextNode(' Sync now'));
  // Update save button to show sync state
  updateSaveButton();
}

function showLoggedOutState() {
  elements.authSection.classList.remove('hidden');
  elements.authLoggedIn.classList.add('hidden');
  elements.authForm.reset();
  elements.authError.classList.add('hidden');
  elements.magicLinkSent.classList.add('hidden');
  elements.authSubmit.disabled = false;
  elements.authMagicLink.disabled = false;
}

async function handleSignIn(e) {
  e.preventDefault();
  const email = elements.authEmail.value.trim();
  const password = elements.authPassword.value;

  if (!email) return;

  elements.authSubmit.disabled = true;
  elements.authError.classList.add('hidden');

  if (password) {
    // Password sign-in
    const result = await signInWithPassword(email, password);
    if (result.error) {
      elements.authError.textContent = result.error;
      elements.authError.classList.remove('hidden');
      elements.authSubmit.disabled = false;
      return;
    }
    authSession = result.session;
    showLoggedInState(result.session.user);
    // Trigger initial sync
    syncSavedArtists();
  } else {
    // Magic link — redirect to OAuth flow
    elements.authSubmit.disabled = false;
    await handleMagicLink(email);
  }
}

async function handleMagicLink(email) {
  if (!email) return;

  elements.authMagicLink.disabled = true;
  elements.authError.classList.add('hidden');

  // Send the magic link email, redirecting to /login — the same page the web
  // app itself uses. content/auth-bridge.js watches that page for the
  // resulting access_token and forwards it to the background service worker,
  // which stores the session. The extension picks up the session on next
  // popup open.
  const result = await signInWithOtp(email, 'https://unstream.stream/login');

  if (result.error) {
    elements.authError.textContent = result.error;
    elements.authError.classList.remove('hidden');
    elements.authMagicLink.disabled = false;
    return;
  }

  // Show "check your email" message
  elements.magicLinkSent.classList.remove('hidden');
  elements.authForm.classList.add('hidden');
  elements.authMagicLink.classList.add('hidden');

  elements.authMagicLink.disabled = false;
}

async function handleSignOut() {
  await signOut();
  authSession = false;
  showLoggedOutState();
  // Clear synced artists — keep only local-only saves
  await clearSyncedArtists();
  loadSavedArtists();
}

async function clearSyncedArtists() {
  // Remove artists that came from server sync, keeping locally-saved ones
  const { syncedArtistSlugs = [] } = await chrome.storage.local.get('syncedArtistSlugs');
  if (syncedArtistSlugs.length === 0) return;

  const { savedArtists = [], savedArtistsData = {} } = await chrome.storage.local.get(['savedArtists', 'savedArtistsData']);
  const remaining = savedArtists.filter(name => !syncedArtistSlugs.includes(name));
  const remainingData = {};
  for (const name of remaining) {
    if (savedArtistsData[name]) remainingData[name] = savedArtistsData[name];
  }

  await chrome.storage.local.set({ savedArtists: remaining, savedArtistsData: remainingData });
  await chrome.storage.local.remove('syncedArtistSlugs');
  await chrome.storage.local.remove('lastSyncTime');
}

// ---- Saved Artists Sync ----

async function syncSavedArtists() {
  if (!authSession) return;

  elements.syncNowBtn.disabled = true;
  elements.syncNowBtn.classList.add('syncing');
  elements.syncNowBtn.textContent = 'Syncing...';

  try {
    const token = authSession.access_token || await getAccessToken();
    if (!token) return;

    const { lastSyncTime } = await chrome.storage.local.get('lastSyncTime');
    const since = lastSyncTime || '1970-01-01T00:00:00Z';

    const response = await fetch(`${API_BASE}/saved-artists/sync?since=${encodeURIComponent(since)}`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });

    if (!response.ok) {
      console.error('Sync failed:', response.status);
      return;
    }

    const data = await response.json();
    const serverArtists = data.artists || [];

    if (serverArtists.length === 0 && !lastSyncTime) {
      // First sync, no server artists — just save the sync timestamp
      await chrome.storage.local.set({ lastSyncTime: data.server_time });
      // Reset the sync button but don't reload the list (nothing changed)
      return;
    }

    // Merge server artists into local state
    const { savedArtists = [], savedArtistsData = {}, syncedArtistSlugs: prevSynced = [] } = await chrome.storage.local.get(['savedArtists', 'savedArtistsData', 'syncedArtistSlugs']);
    const syncedSlugs = [];

    for (const artist of serverArtists) {
      const slug = artist.slug || artist.artistId;
      if (!slug) continue;

      syncedSlugs.push(slug);

      // Add to local list if not present
      if (!savedArtists.includes(slug)) {
        savedArtists.push(slug);
      }

      // Build artist data from server record
      savedArtistsData[slug] = {
        platforms: (artist.claimed && artist.slug) ? [{ sourceId: 'unstream', url: `https://unstream.stream/a/${artist.slug}` }] : [],
        socialLinks: [],
        location: null,
        imageUrl: artist.imageUrl || null,
        name: artist.name || slug,
        slug: artist.slug || '',
        claimed: artist.claimed || false,
        supported: artist.supported || false,
        lastModified: artist.lastModified || null,
      };
    }

    // Union with previously synced slugs so incremental syncs don't lose history
    const mergedSlugs = new Set([...prevSynced, ...syncedSlugs]);

    await chrome.storage.local.set({
      savedArtists,
      savedArtistsData,
      syncedArtistSlugs: [...mergedSlugs],
      lastSyncTime: data.server_time,
    });

    // Reload the saved artists display
    loadSavedArtists();
  } catch (error) {
    console.error('Sync error:', error);
  } finally {
    elements.syncNowBtn.disabled = false;
    elements.syncNowBtn.classList.remove('syncing');
    // Reset button content
    elements.syncNowBtn.innerHTML = '';
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('width', '14');
    svg.setAttribute('height', '14');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('fill', 'none');
    svg.setAttribute('stroke', 'currentColor');
    svg.setAttribute('stroke-width', '2');
    const polyline = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
    polyline.setAttribute('points', '23 4 23 10 17 10');
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', 'M20.49 15a9 9 0 1 1-2.12-9.36L23 10');
    svg.appendChild(polyline);
    svg.appendChild(path);
    elements.syncNowBtn.appendChild(svg);
    elements.syncNowBtn.appendChild(document.createTextNode(' Sync now'));
  }
}

// Save an artist to the server (when logged in)
// artistSlug should be the canonical slug (from lookupSlug), not a display name
async function saveArtistToServer(artistSlug, artistData) {
  if (!authSession) return; // TODO: queue saves fired before initAuth completes

  const token = authSession.access_token || await getAccessToken();
  if (!token) return;

  const deviceId = await getDeviceId();

  try {
    await fetch(`${API_BASE}/saved-artists`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
      },
      body: JSON.stringify({
        artistId: artistSlug,
        name: artistData.name || artistSlug,
        imageUrl: artistData.imageUrl || null,
        last_modified: new Date().toISOString(),
        device_id: deviceId,
      }),
    });
  } catch {
    // Silent — local save is still preserved
  }
}

// Remove an artist from the server (when logged in)
// artistSlug should be the canonical slug
async function removeArtistFromServer(artistSlug) {
  if (!authSession) return;

  const token = authSession.access_token || await getAccessToken();
  if (!token) return;

  try {
    await fetch(`${API_BASE}/saved-artists`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
      },
      body: JSON.stringify({
        action: 'remove',
        artistId: artistSlug,
      }),
    });
  } catch {
    // Silent — local removal is still preserved
  }
}

// Format ArtistLocation object to "City, Country" string
function formatLocation(location) {
  if (!location) return '';
  const region = location.country || location.countryCode;
  if (location.city && region) return `${location.city}, ${region}`;
  if (location.city) return location.city;
  if (region) return region;
  return '';
}

// ---- Custom Sites (user-opted per-site detection, UNS-152) ----

async function getActiveTab() {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  return tab || null;
}

// Decide what (if anything) to show in the "detect on this site" card for the
// active tab: an Enable prompt on unsupported sites, or a gentle "watching but
// nothing detected yet" note on sites already enabled that aren't reporting.
async function setupDetectionControl() {
  detectTarget = null;
  elements.detectSiteSection.classList.add('hidden');
  elements.detectEnableBtn.classList.add('hidden');

  const tab = await getActiveTab();
  // Hide on privileged pages (chrome://, about:, extension pages) and on
  // built-in allowlist sites where detection already runs.
  if (!tab || !tab.url || !isScriptableUrl(tab.url) || isBuiltInSite(tab.url)) return;

  const origin = originPattern(tab.url);
  const host = new URL(tab.url).hostname;
  const sites = await getCustomSites();

  if (sites.includes(origin)) {
    const hasPermission = await chrome.permissions.contains({ origins: [origin] });
    if (!hasPermission) {
      // Permission was revoked out-of-band (e.g. via the browser's own site
      // settings) since we last reconciled — the stored entry is stale. Prune
      // it and fall through to the enable prompt instead of claiming we're
      // still watching.
      await disableSite(origin);
      showDetectEnablePrompt(host, origin, tab.id, sites.length - 1);
      return;
    }

    // Already enabled. If nothing is playing/detected on THIS tab, explain the
    // idle state rather than silently showing nothing (or showing it based on
    // a track that was actually detected on some other tab).
    const { currentTrack } = await chrome.storage.local.get('currentTrack');
    const hasFreshTrack = currentTrack
      && currentTrack.tabId === tab.id
      && Date.now() - currentTrack.timestamp < 5 * 60 * 1000;
    if (!hasFreshTrack) showDetectIdleNote();
    return;
  }

  showDetectEnablePrompt(host, origin, tab.id, sites.length);
}

function showDetectEnablePrompt(host, origin, tabId, siteCount) {
  elements.detectTitle.textContent = 'Detect music on this site?';

  if (siteCount >= MAX_CUSTOM_SITES) {
    elements.detectDesc.textContent = `You've reached the limit of ${MAX_CUSTOM_SITES} custom sites. Remove one in Settings to add another.`;
    elements.detectEnableBtn.classList.add('hidden');
  } else {
    elements.detectDesc.textContent = "Unstream isn't watching this site yet. Turn on detection to find artists you're playing here.";
    elements.detectEnableBtn.textContent = `Enable on ${host}`;
    elements.detectEnableBtn.disabled = false;
    elements.detectEnableBtn.classList.remove('hidden');
    detectTarget = { origin, tabId };
  }

  elements.detectSiteSection.classList.remove('hidden');
}

function showDetectIdleNote() {
  elements.detectTitle.textContent = 'Watching this site';
  elements.detectDesc.textContent = "Unstream is watching this site but hasn't picked up any track info. This site may not share what's playing in a way Unstream can read.";
  elements.detectEnableBtn.classList.add('hidden');
  elements.detectSiteSection.classList.remove('hidden');
}

// Handle the Enable click. Requests the host permission FIRST (directly in the
// user gesture), then registers and injects the generic detector.
async function handleEnableSite() {
  if (!detectTarget) return;
  const { origin, tabId } = detectTarget;

  const granted = await chrome.permissions.request({ origins: [origin] });
  if (!granted) return; // user declined — leave everything untouched

  elements.detectEnableBtn.disabled = true;

  const result = await enableSite(origin);
  if (!result.ok) {
    // Hit the sanity cap — surface it and revoke the just-granted permission.
    await chrome.permissions.remove({ origins: [origin] });
    await setupDetectionControl();
    return;
  }

  // Inject into the already-open tab so the user doesn't have to reload.
  try {
    await chrome.scripting.executeScript({
      target: { tabId },
      files: ['content/common.js', 'content/generic.js'],
    });
  } catch {
    // Some pages block injection; the persistent registration still applies on reload.
  }

  await setupDetectionControl();
  await loadCustomSites();
}

// Render the managed list of enabled custom sites in Settings.
async function loadCustomSites() {
  const sites = await getCustomSites();

  if (sites.length === 0) {
    elements.customSitesList.replaceChildren();
    elements.noCustomSites.style.display = 'block';
    return;
  }

  elements.noCustomSites.style.display = 'none';

  const fragment = document.createDocumentFragment();
  for (const origin of sites) {
    const item = document.createElement('div');
    item.className = 'custom-site-item';

    const hostSpan = document.createElement('span');
    hostSpan.className = 'custom-site-host';
    // Show the bare host (strip scheme and the trailing "/*").
    hostSpan.textContent = origin.replace(/^https?:\/\//, '').replace(/\/\*$/, '');
    hostSpan.title = origin;

    const removeBtn = document.createElement('button');
    removeBtn.className = 'custom-site-remove';
    removeBtn.textContent = 'Remove';
    removeBtn.addEventListener('click', () => removeCustomSite(origin));

    item.appendChild(hostSpan);
    item.appendChild(removeBtn);
    fragment.appendChild(item);
  }

  elements.customSitesList.replaceChildren(fragment);
}

async function removeCustomSite(origin) {
  await disableSite(origin);
  await loadCustomSites();
  await setupDetectionControl();
}

// Initialize popup
async function init() {
  // Initialize auth state
  await initAuth();

  // Get current track from storage
  const { currentTrack } = await chrome.storage.local.get('currentTrack');

  if (currentTrack && Date.now() - currentTrack.timestamp < 5 * 60 * 1000) {
    showNowPlaying(currentTrack);
    await loadResults(currentTrack.artist);
    await loadEnrichment(currentTrack.artist);
  } else {
    // Only in the idle state: an artist on screen always comes first.
    await setupSupportReminder();
  }

  // Show per-site detection control for the active tab, and the managed list
  await setupDetectionControl();
  await loadCustomSites();

  // Load saved artists and releases
  await loadSavedArtists();
  await loadNewReleases();
  await loadLastCheckTime();

  // Initialize artist notification toggle state
  const { artistNotifications } = await chrome.storage.sync.get('artistNotifications');
  document.getElementById('artist-notifications-toggle').checked = artistNotifications !== false; // default enabled

  // Setup event listeners
  setupEventListeners();
}

// The occasional "consider supporting Unstream" callout. Rules in lib/support-reminder.js.
async function setupSupportReminder() {
  const now = Date.now();
  const { [SUPPORT_REMINDER_KEY]: stored } = await chrome.storage.local.get(SUPPORT_REMINDER_KEY);
  const { show, state } = supportReminderDecision(stored, now, isBandcampFriday());
  if (state !== stored) await chrome.storage.local.set({ [SUPPORT_REMINDER_KEY]: state });
  if (!show) return;

  const snooze = async (days) => {
    elements.supportReminder.classList.add('hidden');
    await chrome.storage.local.set({ [SUPPORT_REMINDER_KEY]: snoozeSupportReminder(Date.now(), days) });
  };
  document.getElementById('support-reminder-close').addEventListener('click', () => snooze());
  // Save before the tab opens: opening one closes the popup, which can cut off the write.
  const kofiLink = document.getElementById('support-reminder-kofi');
  kofiLink.addEventListener('click', async (e) => {
    e.preventDefault();
    await snooze();
    chrome.tabs.create({ url: kofiLink.href });
  });
  document.getElementById('support-reminder-already').addEventListener('click', () => snooze(ALREADY_SUPPORT_DAYS));
  elements.supportReminder.classList.remove('hidden');
}

// Show now playing
function showNowPlaying(track) {
  currentArtist = track.artist;
  currentArtistSlug = null; // will be resolved asynchronously
  currentLocation = null;
  bioResult = null;
  elements.artistName.textContent = track.artist;
  elements.artistLocation.textContent = '';
  renderArtistBio(elements.artistBio, null);
  elements.trackTitle.textContent = track.title || '';
  elements.sourceBadge.textContent = track.source;

  elements.nowPlaying.classList.remove('hidden');
  elements.idleState.classList.add('hidden');
  elements.actionsSection.classList.remove('hidden');

  updateSaveButton();

  // Resolve the canonical slug for this artist
  lookupSlug(track.artist).then(slug => {
    currentArtistSlug = slug;
    updateSaveButton();
  });
}

// Hide now playing
function hideNowPlaying() {
  currentArtist = null;
  currentArtistSlug = null;
  currentResults = null;
  currentLocation = null;
  bioResult = null;
  elements.artistLocation.textContent = '';
  renderArtistBio(elements.artistBio, null);
  elements.nowPlaying.classList.add('hidden');
  elements.idleState.classList.remove('hidden');
  elements.resultsSection.classList.add('hidden');
  elements.socialSection.classList.add('hidden');
  elements.actionsSection.classList.add('hidden');
}

// Load results for artist. mode defaults to 'exact' because most lookups here are
// for the detected now-playing artist; the manual search box passes 'fuzzy' so a
// partial name can still find the artist. Returns the results, or undefined when the
// lookup failed.
async function loadResults(artist, mode = 'exact') {
  const loadingDiv = document.createElement('div');
  loadingDiv.className = 'loading';
  loadingDiv.textContent = 'Loading...';
  elements.resultsGrid.replaceChildren(loadingDiv);
  elements.resultsSection.classList.remove('hidden');

  try {
    const response = await chrome.runtime.sendMessage({
      type: 'GET_RESULTS',
      artist,
      mode,
    });

    if (!response || response.error) {
      const errorDiv = document.createElement('div');
      errorDiv.className = 'error';
      errorDiv.textContent = 'Failed to load results';
      elements.resultsGrid.replaceChildren(errorDiv);
      return;
    }

    currentResults = response.results || [];
    renderResults(currentResults);
    return currentResults;
  } catch (error) {
    console.error('loadResults error:', error);
    const errorDiv = document.createElement('div');
    errorDiv.className = 'error';
    errorDiv.textContent = 'Extension is reloading, please try again';
    elements.resultsGrid.replaceChildren(errorDiv);
  }
}

// Render results
function renderResults(results) {
  // Extract claimedSlug for analytics tracking
  const claimedResult = results.find(r => r.type === 'artist' && r.claimedSlug);
  const claimedSlug = claimedResult?.claimedSlug || null;

  // The artist's page slug, for the releases section. `knownSlug` is what makes this work for
  // artists who haven't claimed a page — the vast majority — and it only started coming back from
  // /api/search/sources alongside this feature.
  const pageSlugResult = results.find(r => r.type === 'artist' && (r.claimedSlug || r.knownSlug));
  setArtistReleasesSlug(pageSlugResult?.claimedSlug || pageSlugResult?.knownSlug || null);

  // Extract location: prefer claimed result, otherwise first artist-type result with location
  const locationResult = (claimedResult?.location ? claimedResult : null)
    || results.find(r => r.type === 'artist' && r.location);
  currentLocation = locationResult?.location || null;
  elements.artistLocation.textContent = formatLocation(currentLocation);

  bioResult = bioTarget(results, currentArtist);
  renderArtistBio(elements.artistBio, bioResult?.bio);

  const allPlatforms = [];
  for (const result of results) {
    if (result.platforms && Array.isArray(result.platforms)) {
      for (const platform of result.platforms) {
        allPlatforms.push({ sourceId: platform.sourceId, url: platform.url });
      }
    }
  }

  const seen = new Set();
  const nonSocialPlatforms = allPlatforms.filter(p => {
    if (isSocialSource(p.sourceId)) return false;
    if (isSearchOnlySource(p.sourceId, p.url)) return false;
    if (seen.has(p.sourceId)) return false;
    seen.add(p.sourceId);
    return true;
  });

  // The tip button, for an artist taking tips. It gets the same slug resolution the popup already
  // uses for the artist's page and releases, and the server marks `tipsEnabled` by that same slug.
  // Rendered before the "no alternative sources" case: taking tips does not depend on there being
  // another platform to link to.
  renderTipButton(elements.tipButtonSlot, tipTarget(results, currentArtist));

  if (nonSocialPlatforms.length === 0) {
    const emptyDiv = document.createElement('div');
    emptyDiv.className = 'empty';
    emptyDiv.textContent = 'No alternative sources found';
    elements.resultsGrid.replaceChildren(emptyDiv);
    return;
  }

  const bcFriday = isBandcampFriday();
  const fragment = document.createDocumentFragment();
  nonSocialPlatforms.slice(0, 8).forEach(platform => {
    const config = SOURCE_CONFIG[platform.sourceId] || { icon: '🔗', name: platform.sourceId };
    const link = document.createElement('a');
    link.href = platform.url;
    link.target = '_blank';
    link.className = 'result-item';
    link.title = config.name;
    link.addEventListener('click', () => {
      chrome.runtime.sendMessage({ type: 'TRACK_APP_EVENT', event_type: 'platform_click', context: { platform: platform.sourceId } });
      if (claimedSlug) {
        chrome.runtime.sendMessage({ type: 'TRACK_ANALYTICS', slug: claimedSlug, metric: `click:${platform.sourceId}` });
      }
    });

    const iconSpan = document.createElement('span');
    iconSpan.className = 'result-icon';
    const logoSvg = PLATFORM_LOGOS[platform.sourceId];
    if (logoSvg) {
      const doc = new DOMParser().parseFromString(logoSvg, 'image/svg+xml');
      iconSpan.appendChild(doc.documentElement);
    } else {
      iconSpan.textContent = config.icon;
    }

    const nameSpan = document.createElement('span');
    nameSpan.className = 'result-name';

    // Bandcamp Friday indicator
    if (platform.sourceId === 'bandcamp' && bcFriday) {
      nameSpan.textContent = config.name;
      const bcBadge = document.createElement('span');
      bcBadge.className = 'bc-friday-badge';
      bcBadge.textContent = 'BC Friday!';
      bcBadge.title = "It's Bandcamp Friday! Bandcamp waives their revenue share today, so artists get ~97% of every sale.";
      nameSpan.appendChild(bcBadge);
    } else {
      nameSpan.textContent = config.name;
    }

    // Payout percentage badge
    const payoutPercent = PAYOUT_PERCENTAGES[platform.sourceId];
    if (payoutPercent) {
      const displayPayout = (platform.sourceId === 'bandcamp' && bcFriday) ? '~97%' : payoutPercent;
      const payoutBadge = document.createElement('span');
      payoutBadge.className = 'payout-badge';
      payoutBadge.textContent = displayPayout;
      payoutBadge.title = (platform.sourceId === 'bandcamp' && bcFriday)
        ? "It's Bandcamp Friday! Artists get ~97% of every sale."
        : 'Approximate percentage of a sale the artist receives on this platform.';
      nameSpan.appendChild(payoutBadge);
    }

    link.appendChild(iconSpan);
    link.appendChild(nameSpan);
    fragment.appendChild(link);
  });
  elements.resultsGrid.replaceChildren(fragment);
}

// Check if source is social
function isSocialSource(id) {
  return ['instagram', 'facebook', 'tiktok', 'youtube', 'threads', 'bluesky', 'mastodon', 'peertube'].includes(id);
}

// Check if URL is a search URL
function isSearchUrl(url) {
  if (!url) return true;
  const lowercased = url.toLowerCase();
  const searchPatterns = ['/search', '?q=', '?query=', '/explore', 'duckduckgo.com'];
  return searchPatterns.some(pattern => lowercased.includes(pattern));
}

// Check if source is search-only
function isSearchOnlySource(id, url) {
  const searchOnlyIds = ['ampwall', 'kofi', 'buymeacoffee'];
  if (!searchOnlyIds.includes(id)) return false;
  return isSearchUrl(url);
}

// Load enrichment (MusicBrainz data)
async function loadEnrichment(artist) {
  try {
    const enrichment = await chrome.runtime.sendMessage({
      type: 'GET_ENRICHMENT',
      artist,
    });

    // MusicBrainz matched a same-name artist on another Bandcamp account (Honeycrush in
    // Brooklyn vs Honey Crush in Orlando). Their bio and socials don't belong here — and
    // would be saved with this artist if the fan saved them.
    if (enrichmentIsAnotherArtist(currentResults, enrichment)) {
      currentSocialLinks = null;
      return;
    }

    if (shouldFillBio(bioResult, enrichment)) {
      bioResult = { ...bioResult, bio: enrichment.bio };
      renderArtistBio(elements.artistBio, enrichment.bio);
    }

    if (enrichment && enrichment.socialLinks && enrichment.socialLinks.length > 0) {
      currentSocialLinks = enrichment.socialLinks;
      renderSocialLinks(enrichment.socialLinks);
    } else {
      currentSocialLinks = null;
    }
  } catch (error) {
    console.error('loadEnrichment error:', error);
    currentSocialLinks = null;
  }
}

// Render social links with colored SVG icons
function renderSocialLinks(links) {
  if (links.length === 0) return;

  const fragment = document.createDocumentFragment();

  links.forEach(link => {
    const anchor = document.createElement('a');
    anchor.href = link.url;
    anchor.target = '_blank';
    anchor.className = 'social-link';
    anchor.title = link.platform;

    const iconSvg = SOCIAL_ICONS[link.platform];
    if (iconSvg) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(iconSvg, 'image/svg+xml');
      anchor.appendChild(doc.documentElement);
    }
    fragment.appendChild(anchor);
  });

  elements.socialLinks.replaceChildren(fragment);
  elements.socialSection.classList.remove('hidden');
}

// Update save button state
async function updateSaveButton() {
  if (!currentArtist) return;

  const { savedArtists = [] } = await chrome.storage.local.get('savedArtists');
  // Check by slug if resolved, otherwise fall back to display name
  const key = currentArtistSlug || currentArtist;
  const isSaved = savedArtists.includes(key) || savedArtists.includes(currentArtist);

  const starSpan = document.createElement('span');
  starSpan.className = 'star';

  if (isSaved) {
    starSpan.textContent = '\u2605';
    elements.saveArtistBtn.replaceChildren(starSpan, document.createTextNode(' Saved'));
    elements.saveArtistBtn.classList.add('saved');
  } else {
    starSpan.textContent = '\u2606';
    elements.saveArtistBtn.replaceChildren(starSpan, document.createTextNode(' Save Artist'));
    elements.saveArtistBtn.classList.remove('saved');
  }
}

// Save/unsave artist
async function toggleSaveArtist() {
  if (!currentArtist) return;

  // Resolve slug if not yet available
  const slug = currentArtistSlug || await lookupSlug(currentArtist);
  if (slug) currentArtistSlug = slug;

  const key = slug || currentArtist; // use slug as canonical key, display name as fallback
  const { savedArtists = [], savedArtistsData = {} } = await chrome.storage.local.get(['savedArtists', 'savedArtistsData']);

  // Check both slug and display name for backward compat with pre-migration data
  const existingIndex = savedArtists.indexOf(key);
  const legacyIndex = key !== currentArtist ? savedArtists.indexOf(currentArtist) : -1;
  const index = existingIndex !== -1 ? existingIndex : legacyIndex;

  if (index >= 0) {
    const removedKey = savedArtists[index];
    savedArtists.splice(index, 1);
    delete savedArtistsData[removedKey];
    // Remove from server if logged in
    removeArtistFromServer(removedKey);
  } else {
    savedArtists.push(key);
    const artistData = {
      platforms: [],
      socialLinks: [],
      location: currentLocation || null,
      name: currentArtist, // preserve display name for rendering
      slug: slug || '',
    };

    // Save platforms
    if (currentResults && currentResults.length > 0) {
      for (const result of currentResults) {
        if (result.platforms && Array.isArray(result.platforms)) {
          for (const p of result.platforms) {
            artistData.platforms.push({ sourceId: p.sourceId, url: p.url });
          }
        }
      }
    }

    // Save social links
    if (currentSocialLinks && currentSocialLinks.length > 0) {
      artistData.socialLinks = currentSocialLinks;
    }

    // Save image URL from the claimed/first result if available
    const bestResult = currentResults && currentResults.find(r => r.type === 'artist');
    if (bestResult && bestResult.imageUrl) {
      artistData.imageUrl = bestResult.imageUrl;
    }

    savedArtistsData[key] = artistData;
    // Save to server if logged in
    saveArtistToServer(key, artistData);
  }

  await chrome.storage.local.set({ savedArtists, savedArtistsData });
  updateSaveButton();
  loadSavedArtists();
}

// Load saved artists
async function loadSavedArtists() {
  // Show loading state
  const loadingDiv = document.createElement('div');
  loadingDiv.className = 'loading';
  loadingDiv.textContent = 'Loading saved artists...';
  elements.savedArtistsList.replaceChildren(loadingDiv);

  const { savedArtists = [] } = await chrome.storage.local.get('savedArtists');
  const { savedArtistsData = {} } = await chrome.storage.local.get('savedArtistsData');

  if (savedArtists.length === 0) {
    elements.savedArtistsList.replaceChildren();
    elements.noSavedArtists.style.display = 'block';
    return;
  }

  elements.noSavedArtists.style.display = 'none';

  const fragment = document.createDocumentFragment();
  savedArtists.forEach(artist => {
    const artistData = savedArtistsData[artist] || {};
    const socialLinks = artistData.socialLinks || [];
    const location = artistData.location || null;
    const imageUrl = artistData.imageUrl || null;

    const card = document.createElement('div');
    card.className = 'saved-artist-card';

    // Header with name and remove button
    const header = document.createElement('div');
    header.className = 'saved-artist-header';

    const nameWrap = document.createElement('div');
    nameWrap.className = 'saved-artist-name-wrap';

    // Artist image (if available from server sync)
    // Restrict to https:// only for defense-in-depth
    const safeImageUrl = imageUrl && imageUrl.startsWith('https://') ? imageUrl : '';
    if (safeImageUrl) {
      const img = document.createElement('img');
      img.src = safeImageUrl;
      img.alt = '';
      img.className = 'saved-artist-img';
      img.loading = 'lazy';
      nameWrap.appendChild(img);
    }

    const nameLocationWrap = document.createElement('div');
    nameLocationWrap.className = 'name-location';

    const nameSpan = document.createElement('span');
    nameSpan.className = 'saved-artist-name';
    // Use the synced name if available, otherwise fall back to the key
    nameSpan.textContent = artistData.name || artist;
    nameSpan.addEventListener('click', () => {
      switchToTab('discover');
      searchArtist(artistData.name || artist);
    });
    nameLocationWrap.appendChild(nameSpan);

    const locationText = formatLocation(location);
    if (locationText) {
      const locationSpan = document.createElement('div');
      locationSpan.className = 'saved-artist-location';
      locationSpan.textContent = locationText;
      nameLocationWrap.appendChild(locationSpan);
    }

    nameWrap.appendChild(nameLocationWrap);

    const removeBtn = document.createElement('button');
    removeBtn.className = 'saved-artist-remove';
    removeBtn.title = 'Remove';
    removeBtn.textContent = '\u00D7';
    removeBtn.addEventListener('click', () => removeSavedArtist(artist));

    header.appendChild(nameWrap);
    header.appendChild(removeBtn);
    card.appendChild(header);

    // Social links
    if (socialLinks.length > 0) {
      const socialDiv = document.createElement('div');
      socialDiv.className = 'saved-artist-social';

      socialLinks.forEach(link => {
        const anchor = document.createElement('a');
        anchor.href = link.url;
        anchor.target = '_blank';
        anchor.className = 'social-link-small';
        anchor.title = link.platform;

        const iconSvg = SOCIAL_ICONS[link.platform];
        if (iconSvg) {
          const parser = new DOMParser();
          const doc = parser.parseFromString(iconSvg, 'image/svg+xml');
          anchor.appendChild(doc.documentElement);
        }
        socialDiv.appendChild(anchor);
      });

      card.appendChild(socialDiv);
    }

    fragment.appendChild(card);
  });

  elements.savedArtistsList.replaceChildren(fragment);
}

// Remove saved artist
async function removeSavedArtist(artist) {
  const { savedArtists = [] } = await chrome.storage.local.get('savedArtists');
  const { savedArtistsData = {} } = await chrome.storage.local.get('savedArtistsData');
  const index = savedArtists.indexOf(artist);

  if (index >= 0) {
    savedArtists.splice(index, 1);
    delete savedArtistsData[artist];
    await chrome.storage.local.set({ savedArtists, savedArtistsData });
    // Remove from server if logged in
    removeArtistFromServer(artist);
    loadSavedArtists();
    updateSaveButton();
  }
}

// Load new releases for saved artists
async function loadNewReleases() {
  // Show loading state
  const loadingDiv = document.createElement('div');
  loadingDiv.className = 'loading';
  loadingDiv.textContent = 'Checking releases...';
  elements.newReleases.replaceChildren(loadingDiv);

  try {
    newReleases = await chrome.runtime.sendMessage({ type: 'GET_NEW_RELEASES' }) || [];
  } catch {
    newReleases = [];
  }
  renderNewReleases();
}

// Render new releases section
function renderNewReleases() {
  if (newReleases.length === 0) {
    elements.releasesSection.classList.add('hidden');
    return;
  }

  const fragment = document.createDocumentFragment();
  for (const release of newReleases) {
    fragment.appendChild(buildReleaseItem(release));
  }

  elements.newReleases.replaceChildren(fragment);
  elements.releasesSection.classList.remove('hidden');
}

/**
 * One alert row, with the buying guide folded underneath it.
 *
 * The payout comparison *is* the product, and it matters at the moment someone decides where to
 * buy. Sending that moment to `chrome.tabs.create` handed it to a browser tab \u2014 the same mistake
 * the old alerts made by linking straight to one shop. So the guide expands in place, and
 * opening the web page is the escape hatch rather than the main action.
 */
function buildReleaseItem(release) {
  const wrapper = document.createElement('div');
  wrapper.className = 'new-release-item';

  const row = document.createElement('div');
  row.className = 'release-row';

  const infoDiv = document.createElement('div');
  infoDiv.className = 'release-info';

  const artistSpan = document.createElement('span');
  artistSpan.className = 'release-artist';
  artistSpan.textContent = release.artistName;

  const titleSpan = document.createElement('span');
  titleSpan.className = 'release-title';
  titleSpan.textContent = release.releaseName;

  const subtitle = document.createElement('span');
  subtitle.className = 'release-platform';
  // "out now on Bandcamp and Mirlo \u00b7 from $8 \u00b7 \u2248$6.80 to artist" \u2014 every platform the record is
  // on, then the price, which is the reason to open the guide. Word for word what the
  // notification says, and it names every platform rather than the one the alert leads with:
  // the payout comparison is the product, and this is the moment someone decides where to buy.
  subtitle.textContent = releaseSummaryLine(release);

  infoDiv.appendChild(artistSpan);
  infoDiv.appendChild(titleSpan);
  infoDiv.appendChild(subtitle);

  const actionsDiv = document.createElement('div');
  actionsDiv.className = 'release-actions';

  const slugs = releaseSlugsFromUrl(release.releaseUrl);

  const panel = document.createElement('div');
  panel.className = 'release-guide hidden';

  if (slugs) {
    const toggleBtn = document.createElement('button');
    toggleBtn.className = 'release-open';
    toggleBtn.title = 'Where to buy';
    toggleBtn.textContent = 'Where to buy';
    toggleBtn.setAttribute('aria-expanded', 'false');
    toggleBtn.addEventListener('click', () => toggleReleaseGuide(release, slugs, toggleBtn, panel));
    actionsDiv.appendChild(toggleBtn);
  } else {
    // An alert from the older per-platform scrape path: `releaseUrl` is one shop's, and there is
    // no catalogued release behind it to build a guide from.
    const openBtn = document.createElement('button');
    openBtn.className = 'release-open';
    openBtn.title = 'Listen';
    openBtn.textContent = 'Listen';
    openBtn.addEventListener('click', () => openReleaseUrl(release.releaseUrl));
    actionsDiv.appendChild(openBtn);
  }

  const dismissBtn = document.createElement('button');
  dismissBtn.className = 'release-dismiss';
  dismissBtn.title = 'Dismiss';
  dismissBtn.textContent = '\u00D7';
  dismissBtn.addEventListener('click', async () => {
    await chrome.runtime.sendMessage({ type: 'DISMISS_RELEASE', releaseId: release.id });
    loadNewReleases();
  });
  actionsDiv.appendChild(dismissBtn);

  row.appendChild(infoDiv);
  row.appendChild(actionsDiv);
  wrapper.appendChild(row);
  wrapper.appendChild(panel);
  return wrapper;
}

function openReleaseUrl(url) {
  if (isAllowedReleaseUrl(url)) {
    chrome.tabs.create({ url });
  }
}

/** Fetched guides, keyed by "artist/release", so reopening a row doesn't refetch. */
const releaseGuideCache = new Map();

async function toggleReleaseGuide(release, slugs, toggleBtn, panel) {
  const isOpen = !panel.classList.contains('hidden');
  if (isOpen) {
    panel.classList.add('hidden');
    toggleBtn.setAttribute('aria-expanded', 'false');
    toggleBtn.textContent = 'Where to buy';
    return;
  }

  panel.classList.remove('hidden');
  toggleBtn.setAttribute('aria-expanded', 'true');
  toggleBtn.textContent = 'Hide';

  const key = `${slugs.artist}/${slugs.release}`;
  if (releaseGuideCache.has(key)) {
    renderReleaseGuide(panel, releaseGuideCache.get(key), release.releaseUrl, openReleaseUrl);
    return;
  }

  panel.replaceChildren(guideMessage('Checking where to buy\u2026'));

  try {
    const response = await fetch(
      `${API_BASE}/release/${encodeURIComponent(slugs.artist)}/${encodeURIComponent(slugs.release)}`
    );

    // A 404 means the release genuinely isn't catalogued. Anything else \u2014 a 503 from a database
    // that didn't answer, a rate limit \u2014 means we don't know, and saying "not catalogued" for a
    // question nobody answered would be a convincing lie.
    if (response.status === 404) {
      panel.replaceChildren(
        guideMessage("We haven't catalogued this release yet."),
        guideLink('Open on Unstream', release.releaseUrl, openReleaseUrl)
      );
      return;
    }
    if (!response.ok) throw new Error(`HTTP ${response.status}`);

    const detail = await response.json();
    releaseGuideCache.set(key, detail);
    renderReleaseGuide(panel, detail, release.releaseUrl, openReleaseUrl);
  } catch (error) {
    console.error('[Unstream] Release guide fetch failed:', error);
    panel.replaceChildren(
      guideMessage("Couldn't load prices just now."),
      guideLink('Open on Unstream', release.releaseUrl, openReleaseUrl)
    );
  }
}


// --- Artist releases -------------------------------------------------------
//
// Finding an artist should lead to their records, not stop at a row of platform links. Before
// this, the only route to a buying guide was a release *alert* — which needs the artist saved, a
// scheduled check to have run, and the release to be new — so an album from last year was
// unreachable in the extension entirely.

/** Slug of the artist currently shown, or null when we can't place them. */
let artistReleasesSlug = null;
/** Cached /api/artist-page responses, keyed by slug, for this popup session. */
const artistPageCache = new Map();

function setArtistReleasesSlug(slug) {
  artistReleasesSlug = slug;

  // Collapse whatever the last artist left open — the panel is reused.
  elements.artistReleases.classList.add('hidden');
  elements.artistReleases.replaceChildren();
  elements.artistReleasesToggle.setAttribute('aria-expanded', 'false');

  // No slug means no page to load. An unverified search result is the usual case; nothing
  // persists those, so /api/artist-page would 404.
  elements.artistReleasesSection.classList.toggle('hidden', !slug);
}

async function fetchReleaseDetail(artistSlug, releaseSlug) {
  const response = await fetch(
    `${API_BASE}/release/${encodeURIComponent(artistSlug)}/${encodeURIComponent(releaseSlug)}`
  );
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return response.json();
}

async function toggleArtistReleases() {
  const slug = artistReleasesSlug;
  if (!slug) return;

  const panel = elements.artistReleases;
  const isOpen = !panel.classList.contains('hidden');
  if (isOpen) {
    panel.classList.add('hidden');
    elements.artistReleasesToggle.setAttribute('aria-expanded', 'false');
    return;
  }

  panel.classList.remove('hidden');
  elements.artistReleasesToggle.setAttribute('aria-expanded', 'true');

  if (artistPageCache.has(slug)) {
    renderArtistReleases(panel, artistPageCache.get(slug), slug, fetchReleaseDetail, openReleaseUrl);
    return;
  }

  panel.replaceChildren(guideMessage('Loading releases…'));
  try {
    const response = await fetch(`${API_BASE}/artist-page?slug=${encodeURIComponent(slug)}`);
    // A 404 is a real answer: we have no page for them. Anything else means we don't know, and
    // must not render as "they have no releases".
    if (response.status === 404) {
      panel.replaceChildren(guideMessage("We don't have a page for this artist yet."));
      return;
    }
    if (!response.ok) throw new Error(`HTTP ${response.status}`);

    const page = await response.json();
    artistPageCache.set(slug, page);
    renderArtistReleases(panel, page, slug, fetchReleaseDetail, openReleaseUrl);
  } catch (error) {
    console.error('[Unstream] Artist page fetch failed:', error);
    panel.replaceChildren(guideMessage("Couldn't load releases just now."));
  }
}

// Load last check time, and say so when the last check didn't reach every artist. A failed
// check used to read "No new releases" for a moment and then nothing at all, which told the fan
// everything was fine.
async function loadLastCheckTime() {
  const { releaseCheckState = {} } = await chrome.storage.local.get('releaseCheckState');
  const outcome = releaseCheckState.lastCheckOutcome;
  const formatDate = (ms) => {
    const date = new Date(ms);
    return `${date.toLocaleDateString()} ${date.toLocaleTimeString()}`;
  };

  if (outcome?.status === 'failed') {
    elements.lastCheckTime.textContent =
      "Last check couldn't reach Unstream, so new releases may be missing. Check now to retry.";
  } else if (outcome?.status === 'partial') {
    const checkable = outcome.total - (outcome.uncheckableCount ?? 0);
    elements.lastCheckTime.textContent =
      `Last check reached ${checkable - outcome.failedCount} of ${checkable} artists. Check now to retry the rest.`;
  } else if (releaseCheckState.lastCheckDate) {
    const uncheckable = outcome?.uncheckableCount ?? 0;
    const note = uncheckable === 0 ? ''
      : ` · ${uncheckable} artist${uncheckable === 1 ? '' : 's'} can't be checked until Unstream catalogues them`;
    elements.lastCheckTime.textContent = `Last checked: ${formatDate(releaseCheckState.lastCheckDate)}${note}`;
  }
}

// Check for releases now
async function checkReleasesNow() {
  elements.checkNowBtn.disabled = true;
  elements.checkNowBtn.classList.add('checking');
  elements.checkNowBtn.innerHTML = `
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spinning">
      <polyline points="23 4 23 10 17 10"></polyline>
      <path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"></path>
    </svg>
    Checking...
  `;

  try {
    const result = await chrome.runtime.sendMessage({ type: 'CHECK_RELEASES_NOW' });
    await loadNewReleases();
    await loadLastCheckTime();

    const status = result?.outcome?.status;
    if (result && result.newCount > 0) {
      elements.checkNowBtn.innerHTML = `
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <polyline points="20 6 9 17 4 12"></polyline>
        </svg>
        Found ${result.newCount} new release${result.newCount > 1 ? 's' : ''}!
      `;
    } else if (status === 'failed' || status === 'partial') {
      // Never "No new releases" when some artists weren't checked; the persistent line under
      // the button says how many.
      elements.checkNowBtn.innerHTML = `
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <circle cx="12" cy="12" r="10"></circle>
          <line x1="12" y1="8" x2="12" y2="12"></line>
          <line x1="12" y1="16" x2="12.01" y2="16"></line>
        </svg>
        ${status === 'failed' ? 'Check failed' : 'Check incomplete'}
      `;
    } else {
      elements.checkNowBtn.innerHTML = `
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <polyline points="20 6 9 17 4 12"></polyline>
        </svg>
        No new releases
      `;
    }
  } catch (error) {
    console.error('Check failed:', error);
    elements.checkNowBtn.innerHTML = `
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
        <circle cx="12" cy="12" r="10"></circle>
        <line x1="15" y1="9" x2="9" y2="15"></line>
        <line x1="9" y1="9" x2="15" y2="15"></line>
      </svg>
      Check failed
    `;
  }

  setTimeout(() => {
    elements.checkNowBtn.disabled = false;
    elements.checkNowBtn.classList.remove('checking');
    elements.checkNowBtn.innerHTML = `
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
        <polyline points="23 4 23 10 17 10"></polyline>
        <path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"></path>
      </svg>
      Check for New Releases
    `;
  }, 3000);
}

// Switch to tab
function switchToTab(tabName) {
  elements.tabBtns.forEach(btn => {
    btn.classList.toggle('active', btn.dataset.tab === tabName);
  });
  elements.tabPanels.forEach(panel => {
    panel.classList.toggle('active', panel.id === `tab-${tabName}`);
  });
}

// Manual search (with in-flight guard to prevent API spam)
let searchInFlight = false;

async function searchArtist(artist) {
  if (!artist || searchInFlight) return;

  searchInFlight = true;
  elements.searchBtn.disabled = true;
  elements.searchInput.disabled = true;

  try {
    showNowPlaying({ artist, title: '', source: 'search' });
    const results = await loadResults(artist, 'fuzzy');
    // A typed search: counted here, once, when it completes. The service worker counts
    // now-playing searches itself.
    if (results) {
      chrome.runtime.sendMessage({
        type: 'TRACK_APP_EVENT',
        event_type: 'search',
        context: { has_results: results.length > 0, result_count: results.length, search_kind: 'typed' },
      });
    }
    await loadEnrichment(artist);
  } finally {
    searchInFlight = false;
    elements.searchBtn.disabled = false;
    elements.searchInput.disabled = false;
  }
}

// Open in browser
function openInBrowser() {
  if (!currentArtist) return;
  const encodedQuery = encodeURIComponent(currentArtist);
  chrome.tabs.create({ url: `https://unstream.stream/?q=${encodedQuery}` });
}

// Report issue
function reportIssue(e) {
  e.preventDefault();
  if (!currentArtist) return;

  let platformList = 'No platforms found';
  if (currentResults && currentResults.length > 0) {
    const platforms = [];
    for (const result of currentResults) {
      if (result.platforms && Array.isArray(result.platforms)) {
        for (const platform of result.platforms) {
          platforms.push(`- ${platform.sourceId}: ${platform.url || 'N/A'}`);
        }
      }
    }
    if (platforms.length > 0) {
      platformList = platforms.join('\n');
    }
  }

  const subject = encodeURIComponent(`Issue Report: ${currentArtist}`);
  const body = encodeURIComponent(`Artist/Result: ${currentArtist}

Platforms:
${platformList}

Issue Description:
[Please describe what's wrong with this result]`);

  chrome.tabs.create({ url: `mailto:support@unstream.stream?subject=${subject}&body=${body}` });
}

// Setup event listeners
function setupEventListeners() {
  // Tab navigation
  elements.tabBtns.forEach(btn => {
    btn.addEventListener('click', () => switchToTab(btn.dataset.tab));
  });

  // Save artist
  elements.saveArtistBtn.addEventListener('click', toggleSaveArtist);

  // Open in browser
  elements.openBrowserBtn.addEventListener('click', openInBrowser);

  // Report issue
  elements.reportIssueLink.addEventListener('click', reportIssue);

  // Check now button
  elements.checkNowBtn.addEventListener('click', checkReleasesNow);
  elements.artistReleasesToggle.addEventListener('click', toggleArtistReleases);

  // Artist notifications toggle
  const notifToggle = document.getElementById('artist-notifications-toggle');
  notifToggle.addEventListener('change', async (e) => {
    await chrome.storage.sync.set({ artistNotifications: e.target.checked });
  });

  // Manual search
  elements.searchBtn.addEventListener('click', () => {
    searchArtist(elements.searchInput.value.trim());
  });

  elements.searchInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      searchArtist(elements.searchInput.value.trim());
    }
  });

  // Auth form submission
  elements.authForm.addEventListener('submit', handleSignIn);

  // Magic link button
  elements.authMagicLink.addEventListener('click', () => {
    const email = elements.authEmail.value.trim();
    if (email) {
      handleMagicLink(email);
    }
  });

  // Sign out button
  elements.authSignOut.addEventListener('click', handleSignOut);

  // Sync now button
  elements.syncNowBtn.addEventListener('click', syncSavedArtists);

  // Enable per-site detection
  elements.detectEnableBtn.addEventListener('click', handleEnableSite);
}

// Initialize
init();
